"""Text templates embedded from the full Tobias Holzmann case."""

FILES = {
    '.color': "#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Februar 2025                 #\n#----------------------------------------------#\n# Location:    www.Holzmann-cfd.de             #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n# Color definition for some bash highlight manipulation\n#------------------------------------------------------------------------------\nRED='\\e[0;31m'\nGREEN='\\e[0;32m'\nNC='\\e[0m'\nORANGE='\\033[0;33m'\nGRAY='\\e[0;37m'\nFL='\\033[0;36m'\n\n\n#------------------------------------------------------------------------------\n",
    '.preamble': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Februar 2025                 #\n#----------------------------------------------#\n# Location:    https://Holzmann-cfd.com        #\n# Email:       community@Holzmann-cfd.com      #\n#----------------------------------------------#\n\n\n#------------------------------------------------------------------------------\n# Preamble with the information about the tutorial\necho -en "\n-------------------------------------------------------------------------------\n${GRAY}Tutorial by Tobias Holzmann${NC} :: Generated during February 2015\n${GRAY}Build for OpenFOAM version${NC}  :: OpenFOAM-12\n${GRAY}Tested on system${NC}            :: Ubuntu 24.04.1\n${GRAY}The case was updated on${NC}     :: 10 Februar 2025\n-------------------------------------------------------------------------------\n\n\n${GREEN}Topic: Pseudo 2D Adaptive mesh refinement\nNote: Since v12 the case was set up more realisticly as bugs were removed\n      the changes were necessary${NC}\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\n# Check the OpenFOAM version\necho -e "   - Check OpenFOAM version. We need $foamVersion"\nuserFoamVersion=`echo "$WM_PROJECT-$WM_PROJECT_VERSION"`\n\nif [ "$userFoamVersion" == "$foamVersion" ]\nthen\n    echo -e  "   - ${GREEN}$foamVersion found...${NC}"\n\nelse\n    echo -e  "   - ${ORANGE}You are not using the correct OpenFOAM version"\n    echo -en "     Your version is $userFoamVersion and we need ${GREEN}"\n    echo -e  "$foamVersion${NC}\\n"\n\n    while true\n    do\n        echo -en  "   - Proceed with your OpenFOAM version (y/n): "\n        read proceed\n\n        if [ "$proceed" == "y" ]\n        then\n            break\n\n        elif [ "$proceed" == "n" ]\n        then\n            echo -e "\\n\\n"\n            exit\n\n        fi\n    done\nfi\n\n\n#------------------------------------------------------------------------------\n',
    '0.orig/S': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    object      S;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 0 0 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    inlet\n    {\n        type            codedFixedValue;\n        value           uniform 0;\n\n        name            inletBC;\n\n        code\n        #{\n            const vectorField& faceCenter = this->patch().Cf();\n\n            scalarField values(faceCenter.size(), scalar(0));\n\n            forAll(faceCenter, f)\n            {\n                const point faceCenterPoint = faceCenter[f];\n\n                if (faceCenterPoint.y() > -0.0025 && faceCenterPoint.y() < 0.0025)\n                {\n                    values[f] = scalar(1);\n                }\n            }\n\n            operator==(values);\n        #};\n    }\n\n    side\n    {\n        type            zeroGradient;\n    }\n\n    outlet\n    {\n        type            zeroGradient;\n    }\n\n    cylinder\n    {\n        type            zeroGradient;\n    }\n\n    front\n    {   \n        type            zeroGradient;\n    }\n\n    back \n    {   \n        type            zeroGradient;\n    }\n}\n\n// ************************************************************************* //\n',
    '0.orig/U': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volVectorField;\n    location    "0";\n    object      U;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 1 -1 0 0 0 0];\n\ninternalField   uniform (0 0 0);\n\nboundaryField\n{\n    inlet\n    {\n        type            fixedValue;\n        value           uniform (0.2 0 0);\n    }\n    side\n    {\n        type            slip;\n    }\n    outlet\n    {\n        type            zeroGradient;\n    }\n    cylinder\n    {\n        type            fixedValue;\n        value           uniform (0 0 0);\n    }\n    front\n    {   \n        type            slip;\n    }\n    back \n    {   \n        type            slip;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/p': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    object      p;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -2 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    inlet\n    {\n        type            zeroGradient;\n    }\n    side\n    {\n        type            zeroGradient;\n    }\n    outlet\n    {\n        type            fixedValue;\n        value           $internalField;\n    }\n    cylinder\n    {\n        type            zeroGradient;\n    }\n    front\n    {   \n        type            zeroGradient;\n    }\n    back \n    {   \n        type            zeroGradient;\n    }\n}\n\n// ************************************************************************* //\n',
    'clean': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Last Change: November                        #\n# Topic:                                       #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n#-------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\n\n\n#-------------------------------------------------------------------------------\nfoamCleanTutorials\nrm -rf constant/triSurface/*.eMesh \nrm -rf 0 log* constant/extend*\n\n\n#-------------------------------------------------------------------------------\n',
    'constant/RASProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      RASProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nRASModel        laminar;\n\nturbulence      on;\n\nprintCoeffs     off;\n\n\n// ************************************************************************* //\n',
    'constant/dynamicMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      dynamicMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ntopoChanger\n{\n    type        refiner;\n    libs        ( "libfvMeshTopoChangers.so" );\n    mover       none;\n\n    // How often to refine\n    refineInterval  1;\n\n    // Field to be refinement on\n    field           S;\n\n    // Refine field inbetween lower..upper\n    lowerRefineLevel 0.1;\n    upperRefineLevel 1;\n\n    // Have slower than 2:1 refinement\n    nBufferLayers   1;\n\n    // Refine cells only up to maxRefinement levels\n    maxRefinement   2;\n\n    // Stop refinement if maxCells reached\n    maxCells        400000;\n\n    // Flux field and corresponding velocity field. Fluxes on changed\n    // faces get recalculated by interpolating the velocity. Use \'none\'\n    // on surfaceScalarFields that do not need to be reinterpolated.\n    correctFluxes\n    (\n        (phi none)\n        (nHatf none)\n        (rhoPhi none)\n        (ghf none)\n    );\n\n    // Write the refinement level as a volScalarField\n    dumpLevel       true;\n}\n\n\n// ************************************************************************* //\n',
    'constant/transportProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      transportProperties;\n}\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ntransportModel Newtonian;\n\nnu              nu [0 2 -1 0 0 0 0] 1e-05;\n\n// ************************************************************************* //\n',
    'constant/turbulenceProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      turbulenceProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsimulationType  laminar;\n\n\n// ************************************************************************* //\n',
    'run': '#!/bin/bash\n#\n#-------------------------------------------------#\n# Contributor: Tobias Holzmann                    #\n# Updated on:  10 Februar 2025                    #\n#-------------------------------------------------#\n# Topic:       Adaptive mesh refinement           #\n# OpenFOAM:    version 12 (Foundation)            #\n#-------------------------------------------------#\n# Website:     https://Holzmann-cfd.com           #\n# Email:       community@Holzmann-cfd.com         #\n#-------------------------------------------------#\n\n\n#------------------------------------------------------------------------------\nfoamVersion="OpenFOAM-12"\n\n\n#------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\nsource clean\nsource .color\nsource .preamble\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart meshing\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create background mesh"\nideasUnvToFoam cad/backgroundMesh.unv > logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create surface feature edges"\nsurfaceFeatures >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Meshing with snappyHexMesh"\nsnappyHexMesh -overwrite >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Prepare and clean case for adaptive mesh refinement"\nrm -rf 0\n\n\n#------------------------------------------------------------------------------\necho -e "   - Copy 0.orig to 0"\ncp -r 0.orig 0\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd Meshing\\n\\n"\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart simulation\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Start the simulation (~15 - 30 minutes)"\nfoamRun > logSimulation\n\n\n#------------------------------------------------------------------------------\necho -e "   - Simulation finished, use \'paraFoam\' to check the results"\necho -e "   - Alternative create an empty file with *.foam ending and load it"\necho -e "     in ParaView"\n\n\n#------------------------------------------------------------------------------\n',
    'system/changeDictionaryDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      changeDictionaryDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nboundary\n{\n    front \n    {\n        type            empty;\n    }\n    back \n    {\n        type            empty;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'system/controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     foamRun;\n\nsolver          incompressibleFluid;\n\nstartFrom       latestTime;\n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         5;\n\ndeltaT          1e-6;\n\nwriteControl    adjustableRunTime;\n\nwriteInterval   0.005;\n\npurgeWrite      0;\n\nwriteFormat     ascii;\n\nwritePrecision  10;\n\nwriteCompression off;\n\ntimeFormat      general;\n\ntimePrecision   6;\n\nrunTimeModifiable true;\n\nadjustTimeStep  yes;\n\nmaxCo           0.1;\n\nfunctions\n{\n    scalar\n    {\n        libs            ( "libsolverFunctionObjects.so" );\n        type            scalarTransport;\n        diffusivity     none;\n        field           S;\n        schemesField    S;\n        resetOnStartup  false;\n    }\n}\n\n// ************************************************************************* //\n',
    'system/fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default Euler;\n}\n\ngradSchemes\n{\n    default         Gauss linear;\n    grad(p)         Gauss linear;\n    grad(U)         Gauss linear;\n}\n\ndivSchemes\n{\n    default         none;\n    div(phi,U)      Gauss linearUpwind grad(U);\n    div(phi,S)      Gauss limitedLimitedLinear 1 0 1;\n    div(phi,k)      Gauss limitedLinear 1;\n    div(phi,omega)  Gauss limitedLinear 1;\n\n    div((nuEff*dev2(T(grad(U))))) Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default         Gauss linear limited corrected 0.5;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n}\n\nsnGradSchemes\n{\n    default         corrected;\n}\n\nfluxRequired\n{\n    default         no;\n    pcorr           ;\n    p;\n}\n\n// ************************************************************************* //\n',
    'system/fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    pcorr\n    {\n        solver           GAMG;\n        tolerance        0.02;\n        relTol           0;\n        smoother         GaussSeidel;\n        nPreSweeps       0;\n        nPostSweeps      2;\n        cacheAgglomeration true;\n        agglomerator     faceAreaPair;\n        nCellsInCoarsestLevel 10;\n        mergeLevels      1;\n    }\n\n    pcorrFinal\n    {\n        $pcorr;\n    }\n\n    p\n    {\n        $pcorr\n        tolerance        1e-7;\n        relTol           0.01;\n    }\n\n    pFinal\n    {\n        $p;\n        tolerance        1e-7;\n        relTol           0;\n    }\n\n    "(U|S)"\n    {\n        solver          PBiCG;\n        preconditioner  DILU;\n        tolerance       1e-06;\n        relTol          0.1;\n    }\n\n    "(U|S)Final"\n    {\n        $U;\n        tolerance       1e-06;\n        relTol          0;\n    }\n\n    cellDisplacement\n    {\n        solver          PBiCG;\n        preconditioner  DILU\n        tolerance       1e-5;\n        relTol          0;\n    }\n}\n\nPIMPLE\n{\n    nCorrectors         3;\n    nOuterCorrectors    4;\n    nNonOrthogonalCorrectors 0;\n}\n\nrelaxationFactors\n{\n    fields\n    {\n        p       0.5;\n    }\n\n    equations\n    {\n        U       0.5;\n        S       0.8;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'system/meshQualityDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      meshQualityDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Include defaults parameters from master dictionary\n#includeEtc "caseDicts/mesh/generation/meshQualityDict"\n\nminFaceWeight 0.02;\n\n\n// ************************************************************************* //\n',
    'system/snappyHexMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      snappyHexMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Which of the steps to run\ncastellatedMesh true;\nsnap            true;\naddLayers       false;\n\n\n// Geometry. Definition of all surfaces. All surfaces are of class\n// searchableSurface.\n// Surfaces are used\n// - to specify refinement for any mesh cell intersecting it\n// - to specify refinement for any mesh cell inside/outside/near\n// - to \'snap\' the mesh boundary to the surface\ngeometry\n{\n    cylinder\n    {\n        file "cylinder.stl";\n        type triSurfaceMesh;\n        name cylinder;\n    }\n\n    inletRefine\n    {\n        type searchableBox;\n        min (-0.15 -0.01 0);\n        max (-0.14 0.01 1);\n    }\n    inletRefine2\n    {\n        type searchableBox;\n        min (-0.15 -0.005 0);\n        max (-0.145 0.005 1);\n    }\n};\n\n\n\n// Settings for the castellatedMesh generation.\ncastellatedMeshControls\n{\n\n    // Refinement parameters\n    // ~~~~~~~~~~~~~~~~~~~~~\n\n    // If local number of cells is >= maxLocalCells on any processor\n    // switches from from refinement followed by balancing\n    // (current method) to (weighted) balancing before refinement.\n    maxLocalCells 100000;\n\n    // Overall cell limit (approximately). Refinement will stop immediately\n    // upon reaching this number so a refinement level might not complete.\n    // Note that this is the number of cells before removing the part which\n    // is not \'visible\' from the keepPoint. The final number of cells might\n    // actually be a lot less.\n    maxGlobalCells 2000000;\n\n    // The surface refinement loop might spend lots of iterations refining just a\n    // few cells. This setting will cause refinement to stop if <= minimumRefine\n    // are selected for refinement. Note: it will at least do one iteration\n    // (unless the number of cells to refine is 0)\n    minRefinementCells 10;\n\n    // Allow a certain level of imbalance during refining\n    // (since balancing is quite expensive)\n    // Expressed as fraction of perfect balance (= overall number of cells /\n    // nProcs). 0=balance always.\n    maxLoadUnbalance 0.10;\n\n\n    // Number of buffer layers between different levels.\n    // 1 means normal 2:1 refinement restriction, larger means slower\n    // refinement.\n    nCellsBetweenLevels 2;\n\n\n\n    // Explicit feature edge refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies a level for any cell intersected by its edges.\n    // This is a featureEdgeMesh, read from constant/triSurface for now.\n    features\n    (\n        {\n            file "cylinder.eMesh";\n            level 0;\n        }\n    );\n\n\n\n    // Surface based refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies two levels for every surface. The first is the minimum level,\n    // every cell intersecting a surface gets refined up to the minimum level.\n    // The second level is the maximum level. Cells that \'see\' multiple\n    // intersections where the intersections make an\n    // angle > resolveFeatureAngle get refined up to the maximum level.\n\n    refinementSurfaces\n    {\n        cylinder \n        {\n            // Surface-wise min and max refinement level\n            level (1 2);\n\n            // Optional specification of patch type (default is wall). No\n            // constraint types (cyclic, symmetry) etc. are allowed.\n            patchInfo\n            {\n                type wall;\n            }\n        }\n\n    }\n\n    // Resolve sharp angles\n    resolveFeatureAngle 30;\n\n\n    // Region-wise refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies refinement level for cells in relation to a surface. One of\n    // three modes\n    // - distance. \'levels\' specifies per distance to the surface the\n    //   wanted refinement level. The distances need to be specified in\n    //   descending order.\n    // - inside. \'levels\' is only one entry and only the level is used. All\n    //   cells inside the surface get refined up to the level. The surface\n    //   needs to be closed for this to be possible.\n    // - outside. Same but cells outside.\n\n    refinementRegions\n    {\n        inletRefine\n        {\n            levels ((0 1));\n            mode inside;\n        }\n        inletRefine2\n        {\n            levels ((0 2));\n            mode inside;\n        }\n    }\n\n\n    // Mesh selection\n    // ~~~~~~~~~~~~~~\n\n    // After refinement patches get added for all refinementSurfaces and\n    // all cells intersecting the surfaces get put into these patches. The\n    // section reachable from the locationInMesh is kept.\n    // NOTE: This point should never be on a face, always inside a cell, even\n    // after refinement.\n    locationInMesh (0.1 0 0.005);\n\n\n    // Whether any faceZones (as specified in the refinementSurfaces)\n    // are only on the boundary of corresponding cellZones or also allow\n    // free-standing zone faces. Not used if there are no faceZones.\n    allowFreeStandingZoneFaces false;\n}\n\n\n\n// Settings for the snapping.\nsnapControls\n{\n    //- Number of patch smoothing iterations before finding correspondence\n    //  to surface\n    nSmoothPatch 3;\n\n    //- Relative distance for points to be attracted by surface feature point\n    //  or edge. True distance is this factor times local\n    //  maximum edge length.\n    tolerance 2.0;\n\n    //- Number of mesh displacement relaxation iterations.\n    nSolveIter 300;\n\n    //- Maximum number of snapping relaxation iterations. Should stop\n    //  before upon reaching a correct mesh.\n    nRelaxIter 5;\n\n    // Feature snapping\n\n        //- Number of feature edge snapping iterations.\n        //  Leave out altogether to disable.\n        nFeatureSnapIter 10;\n\n        //- Detect (geometric only) features by sampling the surface\n        //  (default=false).\n        implicitFeatureSnap false;\n\n        //- Use castellatedMeshControls::features (default = true)\n        explicitFeatureSnap true;\n\n        //- Detect points on multiple surfaces (only for explicitFeatureSnap)\n        multiRegionFeatureSnap false;\n}\n\n\n\n// Settings for the layer addition.\naddLayersControls\n{\n    // Are the thickness parameters below relative to the undistorted\n    // size of the refined cell outside layer (true) or absolute sizes (false).\n    relativeSizes true;\n\n    // Per final patch (so not geometry!) the layer information\n    layers\n    {\n        cylinder        \n        {\n            nSurfaceLayers 3;\n        }\n    }\n\n    // Expansion factor for layer mesh\n    expansionRatio 1.1;\n\n    // Wanted thickness of final added cell layer. If multiple layers\n    // is the\n    // thickness of the layer furthest away from the wall.\n    // Relative to undistorted size of cell outside layer.\n    // is the thickness of the layer furthest away from the wall.\n    // See relativeSizes parameter.\n    finalLayerThickness 0.2;\n\n    // Minimum thickness of cell layer. If for any reason layer\n    // cannot be above minThickness do not add layer.\n    // Relative to undistorted size of cell outside layer.\n    minThickness 0.1;\n\n    // If points get not extruded do nGrow layers of connected faces that are\n    // also not grown. This helps convergence of the layer addition process\n    // close to features.\n    // Note: changed(corrected) w.r.t 17x! (didn\'t do anything in 17x)\n    nGrow 0;\n\n    // Advanced settings\n\n    // When not to extrude surface. 0 is flat surface, 90 is when two faces\n    // are perpendicular\n    featureAngle 60;\n\n    // At non-patched sides allow mesh to slip if extrusion direction makes\n    // angle larger than slipFeatureAngle.\n    slipFeatureAngle 30;\n\n    // Maximum number of snapping relaxation iterations. Should stop\n    // before upon reaching a correct mesh.\n    nRelaxIter 3;\n\n    // Number of smoothing iterations of surface normals\n    nSmoothSurfaceNormals 1;\n\n    // Number of smoothing iterations of interior mesh movement direction\n    nSmoothNormals 3;\n\n    // Smooth layer thickness over surface patches\n    nSmoothThickness 10;\n\n    // Stop layer growth on highly warped cells\n    maxFaceThicknessRatio 0.5;\n\n    // Reduce layer growth where ratio thickness to medial\n    // distance is large\n    maxThicknessToMedialRatio 0.3;\n\n    // Angle used to pick up medial axis points\n    // Note: changed(corrected) w.r.t 17x! 90 degrees corresponds to 130 in 17x.\n    minMedianAxisAngle 90;\n\n\n    // Create buffer region for new layer terminations\n    nBufferCellsNoExtrude 0;\n\n\n    // Overall max number of layer addition iterations. The mesher will exit\n    // if it reaches this number of iterations; possibly with an illegal\n    // mesh.\n    nLayerIter 50;\n}\n\n\n\n// Generic mesh quality settings. At any undoable phase these determine\n// where to undo.\nmeshQualityControls\n{\n    #include "meshQualityDict"\n\n\n    // Advanced\n\n    //- Number of error distribution iterations\n    nSmoothScale 4;\n    //- amount to scale back displacement at error points\n    errorReduction 0.75;\n}\n\n\n// Advanced\n\n// Write flags\nwriteFlags\n(\n    scalarLevels\n    layerSets\n    layerFields     // write volScalarField for layer coverage\n);\n\n\n// Merge tolerance. Is fraction of overall bounding box of initial mesh.\n// Note: the write tolerance needs to be higher than this.\nmergeTolerance 1e-6;\n\n\n// ************************************************************************* //\n',
    'system/surfaceFeaturesDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      surfaceFeatureExtractDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nfeatureEdges\n{\n    // The files of which you want to extract the features\n    // Located in constant/triSurface\n    surfaces\n    (\n        "cylinder.stl"\n    );\n\n    //- Since 6.x\n    //  Needed especially for bad triangulations.\n    //  Always check your feature edge mesh\n    trimFeatures\n    {\n        //- Feature edges that contains less than \'minElem\' of edges are\n        //  removed automatically\n        minElem 5;\n\n        //- Remove feature edges that are less than the total length of [m]\n        minLen  0.001;\n    }\n\n    //- This is the angle between faces\n    includedAngle       150;\n\n    //- Since 6.x\n    //  Outputs the curvature of the surface\n    //curvature           no;\n\n    //- Since 6.x\n    //  Outputs the priximity of points and edges to each other\n    //featureProximity    no;\n\n    //- Since 6.x\n    //  The maximum search distance to use, when looking for other feature\n    //  points and edges\n    //maxFeatureProximity  1;\n\n    //- Write features for post processing into *.obj format\n    //  *.obj can be read by ParaView\n    writeObj            yes;\n\n    //- Write the surface proximity and curvature to the VTK format\n    writeVTK            no;\n}\n\n\n// ************************************************************************* //\n',
}
